// EXPORTS: getDailyIndex, getDateKey, formatDateCN, getUpdateLabel, shuffleByDate, shuffleBySeed
// 基于当前日期的每日轮换工具，确保同一天内容稳定，跨天变化

// 有效日期判定：每天早上8:00才切换到当天数据
// 8:00 之前显示前一天的数据，保持和用户作息一致
export function getEffectiveDate(date?: Date): Date {
  const d = date ? new Date(date) : new Date();
  if (d.getHours() < 8) {
    d.setDate(d.getDate() - 1);
  }
  return d;
}

export function getDateKey(date?: Date): string {
  const d = getEffectiveDate(date);
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
}

export function formatDateCN(date?: Date): string {
  const d = getEffectiveDate(date);
  return `${d.getFullYear()}年${d.getMonth() + 1}月${d.getDate()}日`;
}

export function formatDateShort(date?: Date): string {
  const d = getEffectiveDate(date);
  return `${d.getMonth() + 1}月${d.getDate()}日`;
}

// 用日期做确定性种子，返回 0..total-1 范围内的索引
export function getDailyIndex(total: number, date?: Date): number {
  const d = getEffectiveDate(date);
  // 将年月日转化为一个整数种子
  const seed = d.getFullYear() * 10000 + (d.getMonth() + 1) * 100 + d.getDate();
  // 简单的散列：Knuth 乘法哈希
  const hash = (seed * 2654435761) >>> 0;
  return hash % total;
}

// 基于日期种子从数组中截取一段（每日轮换不同子集）
export function getDailySlice<T>(arr: T[], count: number, date?: Date): T[] {
  if (arr.length <= count) return arr;
  const start = getDailyIndex(arr.length - count + 1, date);
  return arr.slice(start, start + count);
}

// 根据索引和当天日期，生成「最近 N 天」的相对时间描述
// dayIndex: 0 = 今天, 1 = 昨天, 2 = 2天前...
// timeStr: 'HH:mm' 格式的当日时间
// 返回如 '今天 08:30' / '昨天 14:20' / '2天前' / '8月12日 09:15'
export function formatRelativeTime(dayIndex: number, timeStr: string, date?: Date): string {
  const now = date ?? new Date();
  const target = new Date(now);
  target.setDate(now.getDate() - dayIndex);
  const month = target.getMonth() + 1;
  const day = target.getDate();
  if (dayIndex === 0) return `今天 ${timeStr}`;
  if (dayIndex === 1) return `昨天 ${timeStr}`;
  if (dayIndex <= 3) return `${dayIndex}天前`;
  return `${month}月${day}日 ${timeStr}`;
}

// 市场早讯专用：今日/昨日 + 具体日期混合格式
export function formatMorningTime(dayIndex: number, timeStr: string, date?: Date): string {
  const now = date ?? new Date();
  const target = new Date(now);
  target.setDate(now.getDate() - dayIndex);
  const month = target.getMonth() + 1;
  const day = target.getDate();
  if (dayIndex === 0) return `今日 ${timeStr}`;
  if (dayIndex === 1) return `昨日 ${timeStr}`;
  return `${month}月${day}日`;
}

// 顶部显示的「今日更新：MM月DD日 08:00」提示
// 基于有效日期（8点前显示前一天的更新时间）
export function getUpdateLabel(date?: Date): string {
  const d = getEffectiveDate(date);
  const m = d.getMonth() + 1;
  const day = d.getDate();
  return `今日更新：${m}月${day}日 08:00`;
}

// 基于日期种子随机打乱数组（同一天结果稳定）
export function shuffleByDate<T>(arr: T[], date?: Date): T[] {
  const d = getEffectiveDate(date);
  let seed = d.getFullYear() * 10000 + (d.getMonth() + 1) * 100 + d.getDate();
  const random = () => {
    seed = (seed * 9301 + 49297) % 233280;
    return seed / 233280;
  };
  const result = [...arr];
  for (let i = result.length - 1; i > 0; i--) {
    const j = Math.floor(random() * (i + 1));
    [result[i], result[j]] = [result[j], result[i]];
  }
  return result;
}

// 基于自定义种子随机打乱数组（seedOffset 用于「换一批」手动偏移）
export function shuffleBySeed<T>(arr: T[], baseSeed: number, seedOffset = 0, count?: number): T[] {
  let seed = baseSeed + seedOffset * 7919;
  const random = () => {
    seed = (seed * 9301 + 49297) % 233280;
    return seed / 233280;
  };
  const result = [...arr];
  for (let i = result.length - 1; i > 0; i--) {
    const j = Math.floor(random() * (i + 1));
    [result[i], result[j]] = [result[j], result[i]];
  }
  return count ? result.slice(0, Math.min(count, result.length)) : result;
}
